#!/usr/bin/env python3
from pathlib import Path
import pandas as pd,numpy as np,json
root=Path(__file__).resolve().parents[1];o=root/'outputs';w=root/'work';fin=pd.read_csv(o/'stage6_foxp2_gnomad_narrow_variants.csv').set_index('rs');nfe=pd.read_csv(o/'stage6_foxp2_gnomad_nfe_variant_index.csv').set_index('rs').loc[fin.index];d=pd.read_csv(w/'stage6_foxp2_susie_aligned.csv').set_index('rs').loc[fin.index];fa=np.where(fin.sign_to_anchor==1,fin.gnomad_af_alt,1-fin.gnomad_af_alt);na=np.where(nfe.sign_to_anchor==1,nfe.gnomad_af_alt,1-nfe.gnomad_af_alt);h=np.where(d.ea_f==d.anchor_effect_allele,d.effect_allele_frequency_f,1-d.effect_allele_frequency_f);m=d.effect_allele_frequency_m.to_numpy();rf=abs(fa-h);rn=abs(na-m);n=len(fin);R=np.fromfile(w/'stage6_foxp2_gnomad_fin_narrow_ld.bin',dtype='<f8').reshape(n,n);ix={rs:i for i,rs in enumerate(fin.index)};a=ix['rs35624276'];s=pd.read_csv(o/'stage6_foxp2_sisu_anchor_r2_comparison.csv.gz');s=s[(s.anchor=='rs35624276')&s.variant.isin(ix)].copy();s['gnomad_fin_r2']=[R[a,ix[k]]**2 for k in s.variant];s.to_csv(o/'stage6_foxp2_gnomad_sisu_crosscheck.csv.gz',index=False,compression='gzip');result={'n_variants':n,'mean_absolute_AF_diff_mvp_vs_nfe':float(np.mean(rn)),'mean_absolute_AF_diff_hfrs_vs_fin':float(np.mean(rf)),'AF_diff_gt_0_2_mvp_nfe':int(sum(rn>.2)),'AF_diff_gt_0_2_hfrs_fin':int(sum(rf>.2)),'n_sisu_anchor_comparable':len(s),'mean_abs_r2_diff_fin_sisu':float(np.mean(abs(s.gnomad_fin_r2-s.sisu_r2))),'r2_correlation_fin_sisu':float(s.gnomad_fin_r2.corr(s.sisu_r2)),'note':'SISu comparison is to one selected anchor; nearby SNP observations are correlated.'};(o/'stage6_foxp2_gnomad_external_qc.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
